describe("doctests of sympy.series.limits", () => {
  it("Limit(sin(x)/x, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(new Limit([mul(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), fn('sin', [x], { evaluate: false })), x, Rational.of(0n, 1n, { gcd: 1n })], '+'))).toBe('Limit(sin(x)/x, x, 0, dir=\'+\')');
  });
  it("Limit(1/x, x, 0, dir=\"-\")", () => {
    const x = new Sym('x');
    expect(sympyStr(new Limit([pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, Rational.of(0n, 1n, { gcd: 1n })], '-'))).toBe('Limit(1/x, x, 0, dir=\'-\')');
  });
  it("limit(sin(x)/x, x, 0)", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(mul(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), fn('sin', [x], { evaluate: false })), x, Rational.of(0n, 1n, { gcd: 1n }), '+'))).toBe('1');
  });
  it("limit(1/x, x, 0) # default dir='+'", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, Rational.of(0n, 1n, { gcd: 1n }), '+'))).toBe('oo');
  });
  it("limit(1/x, x, 0, dir=\"-\")", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, Rational.of(0n, 1n, { gcd: 1n }), '-'))).toBe('-oo');
  });
  it("limit(1/x, x, 0, dir='+-')", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, Rational.of(0n, 1n, { gcd: 1n }), '+-'))).toBe('zoo');
  });
  it("limit(1/x, x, oo)", () => {
    const x = new Sym('x');
    expect(sympyStr(limit(pow(x, Rational.of(-1n, 1n, { gcd: 1n })), x, oo, '+'))).toBe('0');
  });
});

